CREATE TRIGGER task_status_transition
BEFORE UPDATE OF status ON tasks
WHEN NEW.status IS NOT OLD.status
	AND (OLD.status, NEW.status) NOT IN (VALUES ('open', 'doing'), ('doing', 'open'), ('open', 'done'), ('doing', 'done'), ('open', 'cancelled'), ('doing', 'cancelled'), ('done', 'open'), ('cancelled', 'open'))
BEGIN
	SELECT RAISE(ABORT, 'illegal task transition ' || OLD.status || '->' || NEW.status);
END;

CREATE TRIGGER proposal_status_transition
BEFORE UPDATE OF status ON proposals
WHEN NEW.status IS NOT OLD.status
	AND (OLD.status, NEW.status) NOT IN (VALUES ('pending', 'accepted'), ('pending', 'rejected'), ('pending', 'superseded'))
BEGIN
	SELECT RAISE(ABORT, 'illegal proposal transition ' || OLD.status || '->' || NEW.status);
END;

CREATE TRIGGER task_close_needs_completion
BEFORE UPDATE OF status ON tasks
WHEN NEW.status IN ('done', 'cancelled') AND NEW.status IS NOT OLD.status AND NOT EXISTS (
	SELECT 1 FROM completions c
	WHERE c.id = (SELECT max(id) FROM completions WHERE task_id = NEW.id)
		AND c.status = NEW.status AND c.at = NEW.updated_at
)
BEGIN
	SELECT RAISE(ABORT, 'task ' || NEW.id || ' entering ' || NEW.status || ' needs its latest completion row (' || NEW.status || ' at ' || NEW.updated_at || ')');
END;

CREATE TRIGGER skill_insert_unrated
BEFORE INSERT ON skills
WHEN NEW.level IS NOT NULL
BEGIN
	SELECT RAISE(ABORT, 'skill ' || NEW.key || ' must be inserted unrated; a level arrives only by update with an assessment');
END;

CREATE TRIGGER skill_level_needs_assessment
BEFORE UPDATE OF level ON skills
WHEN NEW.level IS NOT OLD.level AND NOT EXISTS (
	SELECT 1 FROM assessments a
	WHERE a.id = (SELECT max(id) FROM assessments WHERE skill = NEW.key)
		AND a.level = NEW.level AND a.at = NEW.level_at
)
BEGIN
	SELECT RAISE(ABORT, 'skill ' || NEW.key || ' level ' || quote(OLD.level) || '->' || quote(NEW.level) || ' needs its latest assessment row (level ' || quote(NEW.level) || ' at ' || quote(NEW.level_at) || ')');
END;

CREATE TRIGGER dependency_insert_open_tasks
BEFORE INSERT ON dependencies
WHEN EXISTS (SELECT 1 FROM tasks WHERE id IN (NEW.task_id, NEW.blocker_id) AND status IN ('done', 'cancelled'))
BEGIN
	SELECT RAISE(ABORT, 'dependency ' || NEW.blocker_id || ' blocks ' || NEW.task_id || ' touches a closed task');
END;

CREATE TRIGGER dependency_delete_open_tasks
BEFORE DELETE ON dependencies
WHEN EXISTS (SELECT 1 FROM tasks WHERE id IN (OLD.task_id, OLD.blocker_id) AND status IN ('done', 'cancelled'))
BEGIN
	SELECT RAISE(ABORT, 'dependency ' || OLD.blocker_id || ' blocks ' || OLD.task_id || ' touches a closed task; closing keeps edges (K7)');
END;
